    S('js/mod-forge3d.js', 1773, '\'<p class="hint cf-forge3d-motif-off">aucune finition holographique : \'\r\n        + \'ces calques ne s\\\'incrusteront nulle part (le canal d\\\'epaisseur \'\r\n        + \'n\\\'existe qu\\\'en argent ou dorure) — la construction le dira aussi.\'\r\n        + \'</p>\'', '\'<p class="hint cf-forge3d-motif-off">\' + dzT("cartes.forge3d.motifs_morts") + \'</p>\'', {'cartes.forge3d.motifs_morts': ("aucune finition holographique : ces calques ne s'incrusteront nulle part (le canal d'epaisseur n'existe qu'en argent ou dorure) — la construction le dira aussi.", 'no holographic finish: these layers will not be inlaid anywhere (the thickness channel only exists with argent or dorure) — the build will say so too.')}),
    S('js/mod-forge3d.js', 1779, '\'<p class="hint cf-forge3d-motifs"><b>motifs</b> — sources non \'\r\n        + \'chargees (contrat motif-sources indisponible).</p>\'', '\'<p class="hint cf-forge3d-motifs">\' + dzT("cartes.forge3d.motifs_non_charges") + \'</p>\'', {'cartes.forge3d.motifs_non_charges': ('<b>motifs</b> — sources non chargees (contrat motif-sources indisponible).', '<b>patterns</b> — sources not loaded (motif-sources contract unavailable).')}),
    S('js/mod-forge3d.js', 1783, '\'<p class="hint cf-forge3d-motifs"><b>motifs dans \'\r\n        + \'l\\\'hologramme</b> — aucune source dans ce jeu : importez une image \'\r\n        + \'de calque (Typographie), une matiere de support (Matieres), ou \'\r\n        + \'installez une matiere dans la boutique.\'', '\'<p class="hint cf-forge3d-motifs">\' + dzT("cartes.forge3d.motifs_aucune_source")', {'cartes.forge3d.motifs_aucune_source': ("<b>motifs dans l'hologramme</b> — aucune source dans ce jeu : importez une image de calque (Typographie), une matiere de support (Matieres), ou installez une matiere dans la boutique.", '<b>patterns in the hologram</b> — no source in this deck: import a layer image (Typography), a stock material (Materials), or install a material from the shop.')}),
