    S('js/mod-forge3d.js', 1799, '\'<p class="hint">\' + lim.max + \' calques : le plafond est atteint \'\r\n        + \'(retirez-en un pour en poser un autre).</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.motifs_plafond", { n: lim.max }) + \'</p>\'', {'cartes.forge3d.motifs_plafond': ('{n} calques : le plafond est atteint (retirez-en un pour en poser un autre).', '{n} layers: the cap is reached (remove one to add another).')}),
    S('js/mod-forge3d.js', 1801, '\'<label class="cf-forge3d-sel cf-forge3d-motif-add">ajouter\'', '\'<label class="cf-forge3d-sel cf-forge3d-motif-add">\' + dzT("cartes.forge3d.ajouter") + \'\'', {'cartes.forge3d.ajouter': ('ajouter', 'add')}),
    S('js/mod-forge3d.js', 1802, '\'<select data-field="motif_add"><option value="">— un motif… —\'', '\'<select data-field="motif_add"><option value="">\' + dzT("cartes.forge3d.un_motif") + \'\'', {'cartes.forge3d.un_motif': ('— un motif… —', '— a pattern… —')}),
    S('js/mod-forge3d.js', 1805, '\'<p class="hint"><b>motifs dans l\\\'hologramme</b> — chaque calque \'\r\n      + \'epaissit le film la ou il est clair ; l\\\'ORDRE est l\\\'ordre \'\r\n      + \'d\\\'addition (le premier sert en premier, le suivant ne prend que ce \'\r\n      + \'qui reste).</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.motifs_aide") + \'</p>\'', {'cartes.forge3d.motifs_aide': ("<b>motifs dans l'hologramme</b> — chaque calque epaissit le film la ou il est clair ; l'ORDRE est l'ordre d'addition (le premier sert en premier, le suivant ne prend que ce qui reste).", '<b>patterns in the hologram</b> — each layer thickens the film where it is light; the ORDER is the order of addition (the first is served first, the next only takes what is left).')}),
    S('js/mod-forge3d.js', 1814, '\'<p class="hint">l\\\'ordre compte des qu\\\'une part est < 1 : a part \'\r\n      + \'pleine, chaque calque ne fait qu\\\'ajouter jusqu\\\'au plafond et \'\r\n      + \'l\\\'ordre ne change plus le fichier.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.motifs_ordre") + \'</p>\'', {'cartes.forge3d.motifs_ordre': ("l'ordre compte des qu'une part est < 1 : a part pleine, chaque calque ne fait qu'ajouter jusqu'au plafond et l'ordre ne change plus le fichier.", 'order matters as soon as a share is < 1: at full share, each layer only adds up to the cap and the order no longer changes the file.')}),
    S('js/mod-forge3d.js', 1822, '\'<p class="hint">une source claire <b>plein-cadre</b> a part pleine \'\r\n      + \'ecrase l\\\'arc-en-ciel de base (le film est rempli partout, les \'\r\n      + \'franges disparaissent) : gardez une part basse pour une texture, \'\r\n      + \'montez-la pour un sigle decoupe.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.motifs_plein_cadre") + \'</p>\'', {'cartes.forge3d.motifs_plein_cadre': ("une source claire <b>plein-cadre</b> a part pleine ecrase l'arc-en-ciel de base (le film est rempli partout, les franges disparaissent) : gardez une part basse pour une texture, montez-la pour un sigle decoupe.", 'a light <b>full-frame</b> source at full share crushes the base rainbow (the film is filled everywhere, the fringes vanish): keep a low share for a texture, raise it for a cut-out logo.')}),
    S('js/mod-forge3d.js', 1831, '\'<p class="hint">le motif couvre TOUT l\\\'element et suit ses \'\r\n      + \'proportions (la texture d\\\'epaisseur est carree, etiree comme \'\r\n      + \'l\\\'arc-en-ciel de base) : on n\\\'isole pas une bande.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.motifs_tout") + \'</p>\'', {'cartes.forge3d.motifs_tout': ("le motif couvre TOUT l'element et suit ses proportions (la texture d'epaisseur est carree, etiree comme l'arc-en-ciel de base) : on n'isole pas une bande.", 'the pattern covers the WHOLE element and follows its proportions (the thickness texture is square, stretched like the base rainbow): you cannot isolate a strip.')}),
    S('js/mod-forge3d.js', 1835, '\'<p class="hint">le noeud matiere ne se previsualise pas : le motif se \'\r\n      + \'voit sur l\\\'apercu du plan ou du relief en amont, \'\r\n      + \'et sur l\\\'artefact construit.</p></div>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.motifs_apercu") + \'</p></div>\'', {'cartes.forge3d.motifs_apercu': ("le noeud matiere ne se previsualise pas : le motif se voit sur l'apercu du plan ou du relief en amont, et sur l'artefact construit.", 'the material node has no preview: the pattern shows on the preview of the upstream plane or relief, and on the built artifact.')}),
    S('js/mod-forge3d.js', 1872, '\'<label class="cf-forge3d-sel">matière<select data-field="mat">\'', '\'<label class="cf-forge3d-sel">\' + dzT("cartes.forge3d.matiere") + \'<select data-field="mat">\'', {'cartes.forge3d.matiere': ('matière', 'material')}),
    S('js/mod-forge3d.js', 1873, "'>aucune</option>'", '\'>\' + dzT("cartes.forge3d.aucune") + \'</option>\'', {'cartes.forge3d.aucune': ('aucune', 'none')}),
    S('js/mod-forge3d.js', 1879, '\'<span class="hint"><b>aucune matière</b> — \'', '\'<span class="hint"><b>\' + dzT("cartes.forge3d.aucune_matiere") + \'</b> — \'', {'cartes.forge3d.aucune_matiere': ('aucune matière', 'no material')}),
    L('js/mod-forge3d.js', 1880, '"la boutique de matières est vide (aucune matière installée)."', 'cartes.forge3d.boutique_vide', 'la boutique de matières est vide (aucune matière installée).', 'the material shop is empty (no material installed).'),
    L('js/mod-forge3d.js', 1881, '"contrat /info non chargé."', 'cartes.forge3d.contrat_non_charge_court', 'contrat /info non chargé.', '/info contract not loaded.'),
