    X('js/mod-forge3d.js', 1885, '"aucune"', "valeur de finition comparée à l'id servi par /info"),
    S('js/mod-forge3d.js', 1888, '\'<span class="hint">finitions inconnues (contrat /info non chargé).</span>\'', '\'<span class="hint">\' + dzT("cartes.forge3d.finitions_inconnues") + \'</span>\'', {'cartes.forge3d.finitions_inconnues': ('finitions inconnues (contrat /info non chargé).', 'unknown finishes (/info contract not loaded).')}),
    L('js/mod-forge3d.js', 1890, '"tuile"', 'cartes.forge3d.tuile', 'tuile', 'tile'),
    S('js/mod-forge3d.js', 1899, "'> anisotropie</label>'", '\'> \' + dzT("cartes.forge3d.anisotropie") + \'</label>\'', {'cartes.forge3d.anisotropie': ('anisotropie', 'anisotropy')}),
    S('js/mod-forge3d.js', 1912, '\'<p class="hint">cette matière ne porte AUCUNE carte d\\\'occlusion \'\r\n           + \'(le disque fait foi) : la case ne changera rien au fichier.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.sans_ao") + \'</p>\'', {'cartes.forge3d.sans_ao': ("cette matière ne porte AUCUNE carte d'occlusion (le disque fait foi) : la case ne changera rien au fichier.", 'this material carries NO occlusion map (the disk is the reference): the box will change nothing in the file.')}),
    L('js/mod-forge3d.js', 1921, '"matière inconnue de ce contrat"', 'cartes.forge3d.matiere_inconnue', 'matière inconnue de ce contrat', 'material unknown to this contract'),
    S('js/mod-forge3d.js', 1922, "' — l\\'écran ne peut pas dire ce que cette matière porte '\r\n           + '(occlusion, relief, couleur). Les réglages du graphe, eux, '\r\n           + 'agissent toujours à la construction.</p>'", '\' — \' + dzT("cartes.forge3d.matiere_muette") + \'</p>\'', {'cartes.forge3d.matiere_muette': ("l'écran ne peut pas dire ce que cette matière porte (occlusion, relief, couleur). Les réglages du graphe, eux, agissent toujours à la construction.", 'the screen cannot tell what this material carries (occlusion, relief, color). The graph settings still apply at build time.')}),
    S('js/mod-forge3d.js', 1934, '\'<p class="hint">cette extrusion n\\\'a <b>pas d\\\'image</b> : la \'\r\n           + \'lumière transmise n\\\'y montre que le décor, et un décor uni n\\\'a \'\r\n           + \'rien à flouter — « verre » et « verre dépoli » y rendent la \'\r\n           + \'<b>même image</b> (mesuré). Le grain du dépoli se voit sur une \'\r\n           + \'couche texturée ; « translucide », lui, se distingue par sa \'\r\n           + \'teinte.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.extrusion_verre") + \'</p>\'', {'cartes.forge3d.extrusion_verre': ("cette extrusion n'a <b>pas d'image</b> : la lumière transmise n'y montre que le décor, et un décor uni n'a rien à flouter — « verre » et « verre dépoli » y rendent la <b>même image</b> (mesuré). Le grain du dépoli se voit sur une couche texturée ; « translucide », lui, se distingue par sa teinte.", 'this extrusion has <b>no image</b>: transmitted light only shows the scenery through it, and plain scenery has nothing to blur — « verre » and « verre dépoli » render the <b>same image</b> there (measured). The frosted grain shows on a textured layer; « translucide » stands out by its tint.')}),
    S('js/mod-forge3d.js', 1944, '\'<p class="hint">cette matière porte sa propre carte de relief : \'\r\n           + \'l\\\'<b>ondulation</b> de la feuille ne sera pas posée (un \'\r\n           + \'matériau glTF n\\\'accepte qu\\\'un relief, et c\\\'est le vôtre qui \'\r\n           + \'gagne). La construction le dira aussi.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.relief_propre") + \'</p>\'', {'cartes.forge3d.relief_propre': ("cette matière porte sa propre carte de relief : l'<b>ondulation</b> de la feuille ne sera pas posée (un matériau glTF n'accepte qu'un relief, et c'est le vôtre qui gagne). La construction le dira aussi.", 'this material carries its own relief map: the foil <b>ripple</b> will not be applied (a glTF material accepts only one relief, and yours wins). The build will say so too.')}),
    S('js/mod-forge3d.js', 1954, '\'<p class="hint">la finition de surface <b>remplace la \'\r\n           + \'micro-surface</b> de la matière (rugosité et métal viennent de \'\r\n           + \'la recette) ; son relief et son occlusion parlent encore. Une \'\r\n           + \'émission « animée » ne pulse que dans l\\\'aperçu du lab Matières \'\r\n           + \': le fichier la porte <b>fixe</b>.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.surface_aide") + \'</p>\'', {'cartes.forge3d.surface_aide': ("la finition de surface <b>remplace la micro-surface</b> de la matière (rugosité et métal viennent de la recette) ; son relief et son occlusion parlent encore. Une émission « animée » ne pulse que dans l'aperçu du lab Matières : le fichier la porte <b>fixe</b>.", 'the surface finish <b>replaces the micro-surface</b> of the material (roughness and metal come from the recipe); its relief and occlusion still apply. An « animated » emission only pulses in the Materials lab preview: the file carries it <b>static</b>.')}),
    S('js/mod-forge3d.js', 1961, '\'<p class="hint">le verre <b>remplace la micro-surface</b> de la \'\r\n           + \'matière (rugosité et métal viennent de la recette) ; son relief \'\r\n           + \'et son occlusion, eux, parlent encore. La lumière transmise est \'\r\n           + \'teintée par la COUCHE elle-même — un vitrail, pas une vitre \'\r\n           + \'blanche.</p>\'', '\'<p class="hint">\' + dzT("cartes.forge3d.verre_aide") + \'</p>\'', {'cartes.forge3d.verre_aide': ('le verre <b>remplace la micro-surface</b> de la matière (rugosité et métal viennent de la recette) ; son relief et son occlusion, eux, parlent encore. La lumière transmise est teintée par la COUCHE elle-même — un vitrail, pas une vitre blanche.', 'glass <b>replaces the micro-surface</b> of the material (roughness and metal come from the recipe); its relief and occlusion still apply. Transmitted light is tinted by the LAYER itself — stained glass, not a clear pane.')}),
    S('js/mod-forge3d.js', 1973, '\'<p class="hint">« translucide » teinte en plus son absorption \'', '\'<p class="hint">\' + dzT("cartes.forge3d.translucide_pref") + \' \'', {'cartes.forge3d.translucide_pref': ('« translucide » teinte en plus son absorption', '« translucide » also tints its absorption')}),
    S('js/mod-forge3d.js', 1975, "'avec la couleur de la matière — aucune matière posée : il ne '\r\n                + 'teinte rien.'", 'dzT("cartes.forge3d.translucide_sans")', {'cartes.forge3d.translucide_sans': ('avec la couleur de la matière — aucune matière posée : il ne teinte rien.', 'with the material color — no material set: it tints nothing.')}),
    S('js/mod-forge3d.js', 1978, "'avec la <b>moyenne de l\\'image</b> de la matière choisie '\r\n                   + '(pas son réglage de couleur : les deux diffèrent sur '\r\n                   + 'toute la boutique).'", 'dzT("cartes.forge3d.translucide_moyenne")', {'cartes.forge3d.translucide_moyenne': ("avec la <b>moyenne de l'image</b> de la matière choisie (pas son réglage de couleur : les deux diffèrent sur toute la boutique).", 'with the <b>average of the image</b> of the chosen material (not its color setting: the two differ across the whole shop).')}),
    S('js/mod-forge3d.js', 1981, '\'avec le réglage de couleur de la matière\'\r\n                   + (ligne.color ? \' (ici \' + esc(String(ligne.color)) + \')\'\r\n                                  : "")\r\n                   + \' — elle n\\\'a pas d\\\'image.\'', 'dzT("cartes.forge3d.translucide_reglage", { ici: ligne.color ? dzT("cartes.forge3d.translucide_ici", { c: esc(String(ligne.color)) }) : "" })', {'cartes.forge3d.translucide_reglage': ("avec le réglage de couleur de la matière{ici} — elle n'a pas d'image.", 'with the material color setting{ici} — it has no image.'), 'cartes.forge3d.translucide_ici': (' (ici {c})', ' (here {c})')}),
